enum L10n {
    /// "auto" in UserDefaults = follow the system language.
    static var current: AppLanguage {
        resolve(UserDefaults.standard.string(forKey: SettingsKey.appLanguage))
    }

    static func resolve(_ raw: String?) -> AppLanguage {
        guard let raw, let lang = AppLanguage(rawValue: raw) else { return .system }
        return lang
    }

    /// Translation completeness diagnostics (dev mode --l10n-check).
    static func missingKeys() -> [String] {
        var out: [String] = []
        for lang in AppLanguage.allCases {
            for key in L10nKey.allCases where tables[lang]?[key] == nil {
                out.append("\(lang.rawValue).\(key.rawValue)")
            }
        }
        return out
    }

    /// Substitutes a value into a translated sentence. The value carries its own
    /// direction — a Latin file name, a figure like "5.1 GB", a version number —
    /// so it is wrapped in Unicode isolates. Without them a right-to-left
    /// sentence pulls the neighbouring punctuation to the wrong end of the value
    /// and "5.1 GB given back." reads as ".5.1 GB given back".
    static func fill(_ key: L10nKey, _ lang: AppLanguage, _ value: String) -> String {
        let isolated = lang.isRTL ? "\u{2068}" + value + "\u{2069}" : value
        return t(key, lang).replacingOccurrences(of: "%@", with: isolated)
    }

    static func t(_ key: L10nKey, _ lang: AppLanguage) -> String {
        tables[lang]?[key] ?? tables[.en]?[key] ?? key.rawValue
    }

    private static let tables: [AppLanguage: [L10nKey: String]] = [
        .en: [
            .memPressureNote: "memory: macOS's own memory-pressure signal colors the row too, and the worse of the two wins",
            .thSwap: "swap % of ram",
            .windowsInDock: "windows in the dock",
            .windowsInDockNote: "an icon appears while a window is open, and a click on it brings the window back",
            .thermalNote: "temperature: the color follows macOS's own thermal state, not a fixed number",
            .aboutTabNews: "what's new", .newsAllReleases: "all releases",
            .docNews: "1.9.1 — 2026-08-31\n\n• signed by apple — hop now carries an apple developer id and apple's notarisation, so macos opens it without the warning a first install used to show. the signature is new, which makes hop a new app to macos: the permissions you had granted are gone, and hop asks for each one again when it needs it\n\n• vpn, faster — a tunnel's state is taken from the system the moment it changes, so the dot in the menu bar follows a connection going up or down without a wait. it holds for clients that leave their interface standing after the session itself is gone\n\n• what a release brought — a card at the top of the panel names what a new version added, with the full notes one button away. it arrives with the update, keeps to a couple of showings and leaves on its own\n\n1.9.0 — 2026-08-29\n\n• projects and history in the tracker — tasks can be grouped into projects, each with its own sum, and one switch above the list shows today, this week or all of it. open a task and every stretch of time it collected is listed: change how long one ran or when it happened, add a session nobody pressed play for, or throw one away. a star now lifts a task to the top of its own list. the row counts the run you are in, from zero, and the ✓ beside it closes the run — the period's sum comes back and the next start begins at zero\n\n• one button for where the video goes — reels, feed, tiktok, shorts or youtube sets the frame, the resolution and how hard to squeeze, from what the platform itself recommends. the dial says the bitrate it means, in megabits, so what you are trading is visible\n\n• mkv and webm at last — macOS opens neither, so hop repacks them into mp4 first, copying the picture across untouched, and everything else works as usual. a small helper downloads once, the first time you convert one\n\n• pages, numbers and keynote — drop a pile of them in and they come out as pdf, or as docx, xlsx and pptx. the documents are exported by the apps themselves, so the result is what «export to…» gives, formulas included\n\n• smaller things — an image asked for in the format it already is, at full quality, is copied instead of re-encoded (it used to come back several times heavier); durations are always written in full, h:mm:ss; and the converter's settings line up in one column\n\n1.8.0 — 2026-08-04\n\n• video for where it is going — a clip can be reframed as it converts: 9:16 for reels and stories, 4:5 or square for a feed, 16:9 for everything else. a picture of another shape is cropped to fill, padded, or laid over a blurred copy of itself — your choice, and nothing is ever stretched\n\n• compression that compresses — the switch used to change almost nothing, because the system's own settings re-encode a video back to about the size it started at. hop now encodes it itself, with a level you set, and the size it promises is the size you get. the container stays what it was: an mp4 comes out an mp4\n\n• two clocks in the menu bar — a timer and a tracked task share the one spot now, five seconds each, with a small mark in front of the digits saying which is speaking. a clock stopped while the panel is open keeps its place instead of leaving a gap\n\n• pdf into markdown, faster — the same text and the same headings in a fraction of the time, up to eight times quicker on documents whose fonts macOS has to work at\n\n• after converting — the bar moves with the work rather than in jumps, a sound says the batch is done, and a button opens the folder the files went to with one already selected. anything macOS cannot open at all (mkv, webm) is named as such the moment you drop it, not after you press convert\n\n1.7.1 — 2026-07-31\n\n• vpn — the dot on the icon turns orange when a tunnel is on but nothing is coming back through it, so a connection that quietly died stops looking like a working one. the panel marks which tunnel it means, and the dot now stays right while the panel is closed\n\n• cleaning up — leftovers belonging to a program you still have installed are no longer offered: on a real Mac seven of the eight rows had an owner\n\n• the cleanup window reads shorter — the line repeated under every row is gone, since the heading above them already says what they are\n\n1.7.0 — 2026-07-30\n\n• removing apps — a new module: drop an app on it or pick it from the list, and it goes together with everything it left behind in a couple of dozen places; whatever macOS refuses to hand over is named rather than quietly skipped\n\n• clearing the cache — the same module tidies up without removing anything: every app holding a cache, installers left in downloads, the data of apps you removed years ago, and the trash. one tick takes a whole section, and the window says what it deliberately leaves alone\n\n• a vpn that stays off — switching one off used to last seconds: its own rules brought the tunnel straight back. now off means off until you switch it on yourself\n\n• copied text into a file — a new icon in the clipboard saves an entry as txt, md, pdf or docx; by default onto the desktop, named after the text itself\n\n• pdf into a word file — the pdf group gained a docx mode beside compress and md\n\n• intel macs — hop runs on them again, as its own download; each build carries only the code its processor runs, so neither is heavier than it was\n\n• tooltips — every icon without a caption now says what it does on hover, including all eighteen window zones, which never had names\n\n• the timer stops jumping — presets and cycles moved below the clock, and the stopwatch toggle stays put at its edge\n\n• fixes — the menu-bar icon no longer disappears against a bar of the other colour, cyrillic text in a pdf copies out correctly, a grid of apps that refused to delete deletes, and the first screen no longer asks about modules you have just chosen",
